import * as THREE from './three.module.js';
export function parquetTexture(anisotropy=1){const c=document.createElement('canvas');c.width=c.height=2048;const ctx=c.getContext('2d');let seed=80421;const rand=()=>{seed=(seed*1664525+1013904223)>>>0;return seed/4294967296;};ctx.fillStyle='#372b20';ctx.fillRect(0,0,2048,2048);
const block=128,plank=32;for(let row=0;row<16;row++)for(let col=0;col<16;col++){ctx.save();ctx.translate(col*block+block/2,row*block+block/2);if((row+col)%2)ctx.rotate(Math.PI/2);ctx.translate(-block/2,-block/2);for(let p=0;p<4;p++){const y=p*plank,tone=rand()*25-12;ctx.fillStyle=`rgb(${135+tone},${101+tone},${62+tone*.7})`;ctx.fillRect(1,y+1,126,30);const grad=ctx.createLinearGradient(0,y,0,y+32);grad.addColorStop(0,'#fff0cd18');grad.addColorStop(.5,'#b5833a08');grad.addColorStop(1,'#190f0c35');ctx.fillStyle=grad;ctx.fillRect(1,y+1,126,30);for(let g=0;g<24;g++){const gy=y+rand()*30+1;ctx.strokeStyle=rand()>.5?'rgba(42,22,8,.07)':'rgba(240,203,140,.06)';ctx.lineWidth=.3+rand()*.7;ctx.beginPath();ctx.moveTo(0,gy);ctx.bezierCurveTo(35,gy-2+rand()*4,78,gy+rand()*3,128,gy-1+rand()*2);ctx.stroke();}if(rand()>.65){const x=20+rand()*80,yy=y+10+rand()*10;ctx.strokeStyle='#38200e29';for(let k=1;k<5;k++){ctx.beginPath();ctx.ellipse(x,yy,k*5,k*.9,.05,0,Math.PI*2);ctx.stroke();}}ctx.strokeStyle='#e1bb7c35';ctx.lineWidth=.7;ctx.strokeRect(1.5,y+1.5,125,29);ctx.fillStyle='#1f160c88';ctx.fillRect(1,y,126,1.2);}ctx.restore();}
// Rubber heel marks and curved sliding scuffs, denser where players stop and turn.
for(let i=0;i<650;i++){const x=80+rand()*1888,y=80+rand()*1888,angle=rand()*Math.PI*2;ctx.save();ctx.translate(x,y);ctx.rotate(angle);const length=8+rand()*80;ctx.strokeStyle=`rgba(26,24,21,${.10+rand()*.24})`;ctx.lineWidth=1+rand()*4;ctx.lineCap='round';ctx.beginPath();ctx.moveTo(0,0);ctx.quadraticCurveTo(length*.45,rand()*15,length,rand()*8);ctx.stroke();if(i%3===0){ctx.strokeStyle='#1d1c1730';ctx.lineWidth=.8;for(let k=1;k<4;k++){ctx.beginPath();ctx.moveTo(0,k*2);ctx.lineTo(length*.8,k*2+2);ctx.stroke();}}ctx.restore();}
for(let i=0;i<2500;i++){const x=rand()*2048,y=rand()*2048;ctx.strokeStyle=rand()>.65?'#f6d39d2b':'#30261920';ctx.lineWidth=.5;ctx.beginPath();ctx.moveTo(x,y);ctx.lineTo(x+rand()*16,y+rand()*3);ctx.stroke();}
const t=new THREE.CanvasTexture(c);t.colorSpace=THREE.SRGBColorSpace;t.anisotropy=anisotropy;return t;}
